target.css:
:root {
  --ink: #263029;
  --muted: #687169;
  --paper: #fffdf7;
  --line: #d9ddd2;
  --leaf: #35634a;
  --leaf-soft: #e4f0e5;
  --wheat: #e6b75d;
  --warm: #fff4dc;
}

* {
  box-sizing: border-box;
}

h1,
p,
dl,
dd {
  margin: 0;
}

.swap-card {
  width: 480px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--paper);
  color: var(--ink);
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  border-bottom: 1px solid var(--line);
}

.eyebrow,
.care-label {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
}

.status {
  padding: 5px 8px;
  border-radius: 999px;
  background: var(--leaf-soft);
  color: var(--leaf);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.7px;
}

.intro {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 15px 16px;
}

.starter-mark {
  display: grid;
  width: 44px;
  height: 44px;
  flex: 0 0 44px;
  place-items: center;
  border-radius: 14px 14px 14px 4px;
  background: var(--wheat);
  color: var(--ink);
  font-size: 22px;
  font-weight: 800;
}

.intro h1 {
  font-size: 20px;
  line-height: 1.1;
  letter-spacing: -0.3px;
}

.intro p {
  margin-top: 4px;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.35;
}

.details {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  margin: 0 16px;
  padding: 11px 0;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.details div {
  min-width: 0;
}

.details div + div {
  padding-left: 12px;
  border-left: 1px solid var(--line);
}

.details dt {
  margin-bottom: 4px;
  color: var(--muted);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.8px;
}

.details dd {
  font-size: 13px;
  font-weight: 700;
  white-space: nowrap;
}

.care {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin: 13px 16px 12px;
  padding: 10px 11px 10px 12px;
  border-radius: 12px;
  background: var(--warm);
}

.care-copy {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.care strong {
  font-size: 13px;
  line-height: 1.2;
}

button {
  border: 0;
  border-radius: 8px;
  padding: 8px 10px;
  background: var(--leaf);
  color: var(--paper);
  font-size: 12px;
  font-weight: 700;
}

.card-footer {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  padding: 0 16px 13px;
  color: var(--muted);
  font-size: 11px;
}

.host {
  color: var(--leaf);
  font-weight: 800;
  letter-spacing: 0.5px;
  white-space: nowrap;
}

